"""Regenerate the version 7 figures with explicit per-replicate HIF warnings."""
from figure_common import *
from plot_main import main_figures
from plot_supp import supplementary_figures
import itertools
def supplement6(d):
    key='supplementary_figure6';fig,axs=grid();fig.subplots_adjust(hspace=1.0);q=pd.read_csv(A/'all_chromosome12_positions_and_date_effects.csv')
    for ax,letter,columns,title in [(axs[0],'A',['R1','R2','R3','R4','R5'],'All measured targets along chromosome 12q'),(axs[1],'B',['R4','R5'],'Local chromosome context on R4 and R5')]:
        z=q.copy() if letter=='A' else q[q.distance_from_DYNLL1_bp.abs().le(2000000)].copy();z['split_mean']=z[columns].mean(axis=1)
        for side,color in [('centromeric','#C56B36'),('telomeric','#9467A8'),('DYNLL1','#236A98')]:
            b=z[z.position_side.eq(side)];ax.scatter(b.position/1e6,b.split_mean,c=color,s=30 if side=='DYNLL1' else 16,alpha=.8,label=side)
        zero(ax);ax.set(xlabel='Brunello gene-position proxy (Mb)',ylabel='Mean alignment contrast');panel(ax,letter,title);register(key,letter,title,z,'all measured genes on 12q' if letter=='A' else '24 measured genes within 2 Mb including DYNLL1','Every originally measured gene in the indicated window is shown. Signed side labels use chromosome coordinates and do not infer U2OS structure, cutting outcomes or copy number. R4 and R5 were already known before this descriptive diagnostic.','unchanged v3 contrasts and coordinate audit')
        if letter=='A':ax.legend(frameon=False,fontsize=7.5,loc='upper left')
    ranks=pd.read_csv(A/'all_model_date_split_ranks.csv');primary=ranks[ranks.model.eq('adaptive_conditional')];v=primary.pivot(index='gene',columns='split',values='mean');ax=axs[2];ax.scatter(v.R1_R3,v.R4_R5,c='#84939D',s=14,alpha=.6);b=v.loc['DYNLL1'];ax.scatter(b.R1_R3,b.R4_R5,c='#236A98',s=32);ax.annotate('DYNLL1',(b.R1_R3,b.R4_R5),xytext=(-5,-9),textcoords='offset points',ha='right',fontsize=7.5);zero(ax);ax.set(xlabel='R1 to R3 mean',ylabel='R4 to R5 mean');title='Original date split for every selected gene';panel(ax,'C',title);register(key,'C',title,primary,'all 67 genes','DYNLL1 remains among the highest point estimates on R4 to R5, with individual-date ranks 12 and 2. Point ranks do not establish statistical separation. Follow-up outcomes were already known and existing all-date control calibration is retained.','all primary split means and ranks')
    ax=axs[3];local=q[q.distance_from_DYNLL1_bp.abs().le(2000000)];z=d.primary[d.primary.gene.isin(local.gene)].merge(local[['gene','position','position_side']],on='gene',validate='many_to_one')
    for side,color in [('centromeric','#C56B36'),('telomeric','#9467A8'),('DYNLL1','#236A98')]:
        b=z[z.position_side.eq(side)];v=b.groupby('batch').effect.median().reindex(DATES);ax.plot(range(5),v,'o-',c=color,ms=3,lw=1,label=side)
        for k,date in enumerate(DATES):ax.scatter(np.full(b.batch.eq(date).sum(),k),b.loc[b.batch.eq(date),'effect'],c=color,s=5,alpha=.2)
    zero(ax);ax.set_xticks(range(5),[f'R{i+1}' for i in range(5)]);ax.set(ylabel='Median alignment contrast',ylim=(-.05,.085));ax.legend(frameon=False,fontsize=7.5,ncol=3,loc='upper center',bbox_to_anchor=(.5,-.22),handlelength=1.,handletextpad=.2,columnspacing=.6);title='Local sides across all five dates';panel(ax,'D',title);register(key,'D',title,z,'24 local genes by five dates','Lines show medians within each side of the original 2 Mb window and the DYNLL1 value. Faint points retain every measured local gene. All local genes, including positive centromeric genes, remain in the summaries.','complete local gene/date effects')
    from review_panels import draw_plate_rank
    draw_plate_rank(axs[4],axs[5])
    ax=axs[6];z=pd.read_csv(A/'quadratic_area_changes_all_genes.csv');ax.scatter(z.mean_primary,z.change,c='#84939D',s=16,alpha=.65);b=z[z.gene.eq('DYNLL1')];ax.scatter(b.mean_primary,b.change,c='#236A98',s=32);zero(ax);ax.set(xlabel='Primary alignment mean',ylabel='Quadratic area minus primary');title='Incremental effect of the area-squared term';panel(ax,'G',title);register(key,'G',title,z,'67 selected gene means','The primary model already adjusts for log area. Median and maximum absolute additional changes are 0.000213 and 0.002062. This diagnoses an incremental model term, not a complete test of size effects.','unchanged primary and quadratic-area models')
    ax=axs[7];z=ranks[ranks.gene.eq('DYNLL1')&ranks.split.eq('R4_R5')].copy();labels={'adaptive_conditional':'Primary','adaptive_conditional_quadratic_area':'Area squared','direct_matching':'Matching','adaptive_unconditional':'Adaptive uncond.','fixed_conditional':'Fixed cond.','fixed_unconditional':'Fixed uncond.'};order=list(labels);z=z.set_index('model').reindex(order).reset_index();ax.plot(z.rank_all_67,range(6),'o',c='#236A98',ms=4);ax.set_yticks(range(6),[labels[k] for k in order],fontsize=7.5);ax.invert_yaxis();ax.set(xlabel='DYNLL1 R4 to R5 point rank among 67',xticks=[1,2],xlim=(.6,2.4));title='Descriptive point ranks across definitions';panel(ax,'H',title);register(key,'H',title,z,'six estimator sensitivities on the same two dates','Every retained definition is shown. The two fixed-radius definitions rank DYNLL1 second; the other four rank it first. Point ranks do not establish statistically resolved ordering; these sensitivities share images and reagents.','complete split ranks under all retained definitions');finish(fig,key)
